                if (bbdesigner$(cnodes[i]).find("> div > div").hasClass("e-plus"))
                    this.model.loadOnDemand ? this._createChildNodesWhenExpand(bbdesigner$(cnodes[i]), true, level, excludeHiddenNodes) : this._expandNode(bbdesigner$(cnodes[i]));
                this._expandByLevel(bbdesigner$(cnodes[i]).find('> ul'), level - 1, excludeHiddenNodes);
