                    this._on(bbdesigner$(shape), ej.eventType.mouseDown, { Param1: obj, Param2: shapelayer }, proxyControl._polyMouseDown);
                    this._off(bbdesigner$(shape), ej.eventType.mouseUp, proxyControl._polyClickFunction);
                    //if (this.model.enableRightClick)
                        //this._off(bbdesigner$(shape), "contextmenu", proxyControl._polyClickFunction);
