                    this._off(bbdesigner$(shape), ej.eventType.mouseMove, proxyControl._polyMoveFunction);
                    this._on(bbdesigner$(shape), ej.eventType.mouseMove, { Param1: shapelayer, Param2: obj }, proxyControl._polyMoveFunction);
