						if (shapelayer.legendSettings != null && (shapelayer.shapeSettings.colorMappings != null || shapelayer.shapeSettings.colorPath != null) && (shapelayer.legendSettings.type == undefined || shapelayer.legendSettings.type == ej.datavisualization.Map.LegendType.Layers))
							shapelayer._generateLegends(this);
