                        "min-height": "15px",
                        "font-size": "12px",
                        "background": "var(--designer-preview-background)",
                        "border": "1px solid var(--designer-primary-border-color)",
                        "box-shadow": "0 2px 4px 0 rgba(0, 0, 0, .12)",
                        "border-radius": "4px",
                        "padding": "10px",
